use std::collections::HashMap;

use reqwest::Method;
use serde::{Deserialize, Serialize};
use time::OffsetDateTime;

use crate::{Bot, Error};

/// Optional article metadata generated by the server.
#[derive(Debug, Clone, Deserialize)]
pub struct LinkPreview {
    pub url: String,
    #[serde(rename = "siteName")]
    pub site_name: String,
    pub title: String,
    #[serde(default)]
    pub description: Option<String>,
    #[serde(default)]
    pub image: Option<PreviewImage>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct PreviewImage {
    pub id: String,
    pub width: u32,
    pub height: u32,
}

/// A single chat message, as returned by the API.
#[derive(Debug, Clone, Deserialize)]
pub struct Message {
    #[serde(default)]
    pub stream: Option<MessageStream>,
    #[serde(default)]
    pub reactions: HashMap<String, String>,
    #[serde(rename = "reactionRevision", default)]
    pub reaction_revision: i64,
    #[serde(default)]
    pub card: Option<serde_json::Value>,
    #[serde(default)]
    pub fields: HashMap<String, serde_json::Value>,
    #[serde(default)]
    pub cancel: bool,
    pub id: String,
    #[serde(rename = "sessionID")]
    pub session_id: String,
    #[serde(rename = "authorID")]
    pub author_id: String,

    pub content: String,
    #[serde(skip)]
    pub command: Option<String>,
    #[serde(skip)]
    pub argument: Option<String>,

    /// Optional plain-text subject of a bot message.
    #[serde(default)]
    pub subject: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub metadata: Option<serde_json::Value>,
    #[serde(rename = "linkPreview", default)]
    pub link_preview: Option<LinkPreview>,
    #[serde(rename = "previewTS", default, with = "time::serde::rfc3339::option")]
    pub preview_ts: Option<OffsetDateTime>,

    /// Present on bot messages sent with one-tap answer options.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub keyboard: Option<Keyboard>,
    /// On a user's answer to a keyboard message: the id of the keyboard
    /// message (`content` carries the chosen option's label).
    #[serde(rename = "replyTo", default, skip_serializing_if = "Option::is_none")]
    pub reply_to: Option<String>,
    /// On a keyboard answer: the machine value of the chosen option.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub value: Option<String>,
    #[serde(default)]
    pub silent: bool,
    #[serde(default)]
    pub read: bool,
    #[serde(default)]
    pub delivered: bool,

    #[serde(rename = "authorTS", with = "time::serde::rfc3339")]
    pub author_ts: OffsetDateTime,
    #[serde(rename = "createTS", with = "time::serde::rfc3339")]
    pub create_ts: OffsetDateTime,
    /// Set once the author bot has edited the message.
    #[serde(rename = "editTS", default, with = "time::serde::rfc3339::option")]
    pub edit_ts: Option<OffsetDateTime>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MessageStream {
    pub status: String,
    pub sequence: i64,
    #[serde(rename = "updatedTS", with = "time::serde::rfc3339")]
    pub updated_ts: OffsetDateTime,
}

/// One tappable choice offered by a keyboard: `label` is shown to the user,
/// `value` is what the bot receives when it is chosen.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct KeyboardOption {
    pub label: String,
    pub value: String,
}

/// A set of one-tap answer options attached to a message. The server stamps
/// `selected` once the user answers; clients render an answered keyboard
/// unclickable.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Keyboard {
    pub options: Vec<KeyboardOption>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub selected: Option<String>,
}

/// Options for sending or broadcasting a bot message.
#[derive(Debug, Clone, Default, Serialize)]
pub struct SendOptions {
    pub stream: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub subject: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub metadata: Option<serde_json::Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub keyboard: Option<Keyboard>,
    pub silent: bool,
}

/// Changes only supplied fields. An empty subject clears it.
#[derive(Debug, Clone, Default, Serialize)]
pub struct EditOptions {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub subject: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub metadata: Option<serde_json::Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub keyboard: Option<Keyboard>,
}

impl Bot {
    /// Posts a message into a session and returns it as created.
    pub async fn send(
        &self,
        session_id: &str,
        content: &str,
        silent: bool,
    ) -> Result<Message, Error> {
        self.send_with_options(
            session_id,
            content,
            SendOptions {
                silent,
                ..Default::default()
            },
        )
        .await
    }

    /// Posts a message with an optional subject or keyboard.
    pub async fn send_with_options(
        &self,
        session_id: &str,
        content: &str,
        options: SendOptions,
    ) -> Result<Message, Error> {
        let mut body = serde_json::to_value(options)?;
        body["content"] = content.into();
        body["ts"] = now().into();
        self.send_message(session_id, body).await
    }

    /// Edits a message the bot authored: `content`, `keyboard` or both. An
    /// already answered keyboard cannot be replaced (409).
    pub async fn edit(
        &self,
        session_id: &str,
        message_id: &str,
        content: Option<&str>,
        keyboard: Option<Vec<KeyboardOption>>,
    ) -> Result<Message, Error> {
        self.edit_with_options(
            session_id,
            message_id,
            EditOptions {
                content: content.map(str::to_owned),
                keyboard: keyboard.map(|options| Keyboard {
                    options,
                    selected: None,
                }),
                ..Default::default()
            },
        )
        .await
    }

    /// Changes content, subject or keyboard without changing other fields.
    pub async fn edit_with_options(
        &self,
        session_id: &str,
        message_id: &str,
        options: EditOptions,
    ) -> Result<Message, Error> {
        let body = serde_json::to_value(options)?;
        self.update_message(session_id, message_id, body).await
    }

    pub async fn start_stream(&self, session_id: &str) -> Result<Message, Error> {
        self.send_message(session_id, serde_json::json!({"stream": true}))
            .await
    }

    /// Send accumulated text at ~500ms intervals; finish with completed or failed.
    pub async fn update_stream(
        &self,
        session_id: &str,
        message_id: &str,
        content: &str,
        sequence: i64,
        status: &str,
    ) -> Result<Message, Error> {
        let body = serde_json::json!({"content": content, "sequence": sequence, "status": status});
        self.inner
            .api_json(
                Method::POST,
                &format!("/session/{session_id}/message/{message_id}/stream"),
                Some(body),
            )
            .await
    }

    pub async fn react(
        &self,
        session_id: &str,
        message_id: &str,
        emoji: &str,
    ) -> Result<Message, Error> {
        self.inner
            .api_json(
                Method::POST,
                &format!("/session/{session_id}/message/{message_id}/reaction"),
                Some(serde_json::json!({"emoji": emoji})),
            )
            .await
    }

    /// Deletes a message the bot authored.
    pub async fn delete(&self, session_id: &str, message_id: &str) -> Result<(), Error> {
        self.inner
            .api(
                Method::DELETE,
                &format!("/session/{session_id}/message/{message_id}"),
                None,
            )
            .await?;
        Ok(())
    }

    /// Shows a typing indicator to the user for a few seconds; call it again
    /// every 3-4s while the bot is still working.
    pub async fn typing(&self, session_id: &str) -> Result<(), Error> {
        self.inner
            .api(Method::POST, &format!("/session/{session_id}/typing"), None)
            .await?;
        Ok(())
    }

    /// Posts a message with one-tap answer options. The user's tap arrives as
    /// an [`crate::Event::Message`] whose content is the chosen option's label, with
    /// `reply_to` set to the keyboard message's id and `value` to the option's
    /// value (a value matching a registered command arrives as
    /// [`crate::Event::Command`] instead).
    pub async fn send_keyboard(
        &self,
        session_id: &str,
        content: &str,
        options: &[KeyboardOption],
    ) -> Result<Message, Error> {
        self.send_with_options(
            session_id,
            content,
            SendOptions {
                keyboard: Some(Keyboard {
                    options: options.to_vec(),
                    selected: None,
                }),
                ..Default::default()
            },
        )
        .await
    }

    /// Sends text, buttons, attachments or cards using the common message payload.
    pub async fn send_message(
        &self,
        session_id: &str,
        mut message: serde_json::Value,
    ) -> Result<Message, Error> {
        if message.get("ts").is_none() {
            message["ts"] = now().into();
        }
        self.inner
            .api_json(
                Method::POST,
                &format!("/session/{session_id}/message"),
                Some(message),
            )
            .await
    }

    pub async fn update_message(
        &self,
        session_id: &str,
        message_id: &str,
        change: serde_json::Value,
    ) -> Result<Message, Error> {
        self.inner
            .api_json(
                Method::POST,
                &format!("/session/{session_id}/message/{message_id}"),
                Some(change),
            )
            .await
    }

    pub async fn get_message(&self, session_id: &str, message_id: &str) -> Result<Message, Error> {
        self.inner
            .api_json(
                Method::GET,
                &format!("/session/{session_id}/message/{message_id}"),
                None,
            )
            .await
    }
}

fn now() -> String {
    OffsetDateTime::now_utc()
        .format(&time::format_description::well_known::Rfc3339)
        .expect("RFC3339 formatting of the current time cannot fail")
}
